#!/bin/sh
# run.sh - one invocation of a calibration class in a throwaway container (the driver's argv entry point).
# usage: run.sh <probe-alloc MIB FILEMIB | bare-alloc MIB FILEMIB | probe-churn THREADS ARENAMAX BADMIB>
# >>> shguard modes=exec (generated by shell-disposition-gate --guard; do not edit)
case $(realpath -- "$0" 2>/dev/null) in */'memory-measurement-calibration/run.sh') _shguard_m='exec' ;; *) if [ "${SHGUARD_MODE-}" = 'pipe' ]; then _shguard_m='pipe'; else _shguard_m='source'; fi ;; esac
# shellcheck disable=SC2317
case $_shguard_m in
  exec) unset _shguard_m ;;
  *) printf '%s: refusing %s invocation (supports: exec; pipe callers set SHGUARD_MODE=pipe)\n' 'run.sh' "$_shguard_m" >&2; unset _shguard_m; return 1 2>/dev/null || exit 1 ;;
esac
# <<< shguard
if [ "${1:-}" = "--help" ] || [ "${1:-}" = "-h" ]; then
  cat <<'USAGE'
usage: run.sh probe-alloc <MIB> <FILEMIB>   class a/b/d: alloc program wrapped by scripts/memprobe.sh
       run.sh bare-alloc  <MIB> <FILEMIB>   class d: the same program without the probe (self-report only)
       run.sh probe-churn <THREADS> <ARENAMAX> <BADMIB>   class c: churn program, settle windows 0/30/120 s
       run.sh --help | --build | --version
Runs the memcal:1 image (build it with: docker build -t memcal:1 memory-measurement-calibration) with --rm,
pinned by --cpuset-cpus $CAL_PIN (default 6-11,18-23), forwards MEASURE_PAD into the container and prints MEASURE lines on stdout.
ARENAMAX 0 leaves MALLOC_ARENA_MAX unset. For probe-churn, BADMIB is the bad-mode threshold: the extra lines
bad_mode_<S>s are 1 when anon_settled_<S>s_mib exceeds it, else 0 (rate metrics).
USAGE
  exit 0
fi
set -eu

HERE=$(cd "$(dirname "$0")" && pwd)
case ${1:-} in
  --build|--version) exec "$HERE/../scripts/memprobe.sh" --build ;;
esac
mode=${1:?mode}
PIN=${CAL_PIN:-6-11,18-23}
PROBE=$HERE/../scripts/memprobe.sh
num() { case ${1:-} in ''|*[!0-9]*) echo "run.sh: '${1:-}' is not a non-negative whole number" >&2; exit 2 ;; esac; }
dk() { docker run --rm --cpuset-cpus "$PIN" -e "MEASURE_PAD=${MEASURE_PAD:-}" "$@"; }
case $mode in
  probe-alloc|bare-alloc)
    mib=${2:?MIB}; fmib=${3:?FILEMIB}; num "$mib"; num "$fmib"
    if [ "$mode" = bare-alloc ]; then
      exec docker run --rm --cpuset-cpus "$PIN" -e "MEASURE_PAD=${MEASURE_PAD:-}" memcal:1 alloc --mib "$mib" --file-mib "$fmib" --hold 1
    fi
    exec docker run --rm --cpuset-cpus "$PIN" -e "MEASURE_PAD=${MEASURE_PAD:-}" -v "$PROBE:/probe/memprobe.sh:ro" memcal:1 \
      /probe/memprobe.sh --interval 0.1 --boundary-line BOUNDARY --settle 0 -- alloc --mib "$mib" --file-mib "$fmib" --hold 1 ;;
  probe-churn)
    thr=${2:?THREADS}; am=${3:?ARENAMAX}; bad=${4:?BADMIB}; num "$thr"; num "$am"; num "$bad"
    amarg=""; [ "$am" = 0 ] || amarg="-e MALLOC_ARENA_MAX=$am"
    rc=0
    # shellcheck disable=SC2086
    out=$(dk $amarg -v "$PROBE:/probe/memprobe.sh:ro" memcal:1 \
      /probe/memprobe.sh --interval 0.5 --boundary-line BOUNDARY --settle 0,30,120 -- churn --threads "$thr" --seconds 5 --idle 126) || rc=$?
    printf '%s\n' "$out"
    printf '%s\n' "$out" | awk -v t="$bad" '$1=="MEASURE" && $2 ~ /^anon_settled_[0-9]+s_mib$/ { n=$2; sub(/^anon_settled_/, "", n); sub(/s_mib$/, "", n); printf "MEASURE bad_mode_%ss %d\n", n, ($3 > t) ? 1 : 0 }'
    exit "$rc" ;;
  *) echo "run.sh: unknown mode '$mode' (try --help)" >&2; exit 2 ;;
esac
